import React from "react";

export function Button({ children, variant = "primary", className = "", ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: "primary" | "secondary" | "outline" | "ghost" | "destructive" }) {
  return <button className={`px-3.5 py-1.5 rounded-[8px] text-xs font-medium transition-colors ${className}`} {...props}>{children}</button>;
}
